import type { Publication } from './publication-manifest';

export const nov06BlogPublications: readonly Publication[] = [{"publicationStatus": "reviewed", "kind": "blog", "slug": "screen-a-va-candidate-with-a-paid-inbox-triage-sample", "title": "Screen a VA candidate with a paid inbox triage sample", "description": "Use a short paid exercise with safe fixture messages to judge how a virtual assistant candidate sorts, drafts, and escalates real inbox work before you hire.", "published": "2026-11-06", "readingMinutes": 5, "heroImage": "/hero/november-6/screen-a-va-candidate-with-a-paid-inbox-triage-sample-hero.webp", "thumbnail": "/thumbnails/november-6/screen-a-va-candidate-with-a-paid-inbox-triage-sample.webp", "heroAlt": "Screen a VA candidate with a paid inbox triage sample", "topic": "paid inbox triage sample", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/what-does-a-paid-work-sample-predict-about-va-performance", "label": "Read the paid-sample research review"}, "sources": [{"label": "O*NET OnLine", "href": "https://www.onetonline.org/"}, {"label": "EEOC employment tests and selection procedures", "href": "https://www.eeoc.gov/laws/guidance/employment-tests-and-selection-procedures"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "set-the-sample-before-you-interview", "heading": "Set the sample before you interview", "paragraphs": ["A paid inbox triage sample should be designed before the first interview so every candidate receives the same task, deadline, and evidence. Write the brief as if an existing assistant were covering the inbox for one morning, with a start state, a cutoff time, and a named reviewer. Keep the exercise short enough to finish in sixty to ninety minutes, because a longer sample mostly measures stamina. State the pay rate and the time limit in the brief so the candidate can plan the work honestly.", "Choose four or five messages that require different judgments rather than five versions of the same request. Include one message that needs a calendar change, one that needs a document, one that needs a polite deferral, and one that should be escalated rather than answered. Add a message from a known contact that looks urgent but conflicts with the approved calendar. That mix reveals whether the candidate reads context or simply clears the newest item first.", "Decide in advance what the candidate will receive and what the reviewer will keep. Send the fixture as a read-only folder with a short cover note that names the deadline and the person to contact if the brief is unclear. Keep the scoring sheet out of the candidate's view. A candidate who knows the exact scoring dimensions will write for the rubric instead of for the client."]}, {"id": "build-the-inbox-fixture-from-safe-records", "heading": "Build the inbox fixture from safe records", "paragraphs": ["Replace every customer name, address, account number, and price with invented but consistent data. Keep the thread structure realistic, including a prior reply, a forwarded note, and an attachment label that does not match the message. Put the fixture in a dedicated mailbox or a shared document that the candidate can open without touching production systems. Remove signatures, phone numbers, and any internal links that would expose real staff or tools.", "Write a short key that tells the reviewer which messages are safe to answer, which need a draft only, and which must be routed to a named owner. The candidate should see the same key except for the routing answers. If the exercise asks for calendar work, provide a blank test calendar and a clear rule about double-booking. A fixture that depends on live access turns a skills test into a security risk.", "Keep the fixture version number in the folder name so two candidates never receive different messages by accident. If you change a message between candidates, reset the comparison and note the change in the review. A small version label prevents a later argument about whether the exercise was fair. The same discipline applies to the scoring sheet and the time limit."]}, {"id": "score-triage-judgment-not-speed-alone", "heading": "Score triage judgment, not speed alone", "paragraphs": ["Use a scorecard with four dimensions: accuracy, priority order, communication, and escalation judgment. Accuracy covers names, dates, amounts, and whether the reply answers the actual question. Priority order asks the candidate to explain why the first item came first, not just to sort by arrival time. Communication covers tone, length, and whether the draft says what happens next.", "Escalation judgment is the dimension most buyers forget to score. A candidate who spots a pricing exception, a legal threat, or a request from an unauthorized contact should stop and route it with evidence. Give credit for a well-written question when the brief is genuinely ambiguous. Penalize silent guessing more heavily than a slow but correct handoff.", "Calibrate the reviewer before the first candidate by scoring one practice submission together. Compare the scores, discuss the evidence, and rewrite any rubric line that two reviewers interpret differently. A scorecard that produces a different answer for the same output is not ready to compare people. Keep the calibrated version with the exercise."]}, {"id": "compare-candidates-on-the-same-evidence", "heading": "Compare candidates on the same evidence", "paragraphs": ["Review the samples in the same order and with the same reviewer, then record one paragraph of evidence for each score. Do not let a strong interview answer overwrite a weak sample, and do not let a polished sample hide a missing attachment. Keep the candidate's written questions beside the output because they show how the person handles uncertainty. If two reviewers disagree, discuss the specific evidence rather than averaging the scores.", "Ask each candidate to walk through one decision after the sample is submitted. Listen for whether the person can name the source, the rule, and the consequence of the choice. A candidate who says the message felt urgent has not explained the decision. A candidate who says the client's contract renewal date made the message important has given you something you can test again."]}, {"id": "watch-for-risky-shortcuts", "heading": "Watch for risky shortcuts", "paragraphs": ["A fast sample can be a warning sign when the candidate invents a policy, promises a refund, or marks a message complete without the requested document. Check whether the candidate used the approved template or quietly wrote a new one. Look for replies that copy the client's wording without checking the underlying record. Those shortcuts often survive a trial period because nobody reads the sent folder closely.", "Also check how the candidate handled the message that should not be answered. A reply that sounds helpful but commits the business to a date, discount, or scope is a serious error. The sample should make that boundary visible without turning the exercise into a trick. Tell candidates in the brief that some messages may need a draft, a question, or an escalation.", "Read the sent folder for tone as well as content, because a technically correct reply can still create a commitment the client did not approve. Look for phrases that imply a guaranteed date, a discount, or a priority the brief did not grant. Ask the candidate what they would do if the client pushed back on the boundary. The answer shows whether the person understands why the limit exists."]}, {"id": "decide-with-a-written-recommendation", "heading": "Decide with a written recommendation", "paragraphs": ["End the review with a one-page recommendation that names the strongest evidence, the main risk, and the first lane you would assign. Separate what the sample proved from what the interview suggested, because the two carry different weight. If the candidate is strong on execution but weak on escalation, say so and plan a narrower first scope. A clear recommendation makes the hiring decision easier to defend later.", "Keep the sample, scorecard, and recommendation for the first review cycle after hiring. Compare the first month of live work with the sample to see which predictions held. If the sample missed a skill the role needs, change the exercise before the next hire rather than blaming the new assistant. The sample is a hiring instrument, and it improves only when you check its results."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "write-a-first-week-access-checklist-for-a-new-assistant", "title": "Write a first-week access checklist for a new assistant", "description": "A system-by-system checklist for granting, reviewing, and removing a new virtual assistant's access during the first week without shared logins or orphaned permissions.", "published": "2026-11-06", "readingMinutes": 5, "heroImage": "/hero/november-6/write-a-first-week-access-checklist-for-a-new-assistant-hero.webp", "thumbnail": "/thumbnails/november-6/write-a-first-week-access-checklist-for-a-new-assistant.webp", "heroAlt": "Write a first-week access checklist for a new assistant", "topic": "first-week access checklist", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/what-does-access-removal-lag-look-like-after-an-assignment-ends", "label": "Read the access removal research review"}, "sources": [{"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "CISA strong passwords guidance", "href": "https://www.cisa.gov/secure-our-world/use-strong-passwords"}, {"label": "FTC protecting personal information guide", "href": "https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business"}], "sections": [{"id": "list-the-systems-the-first-lane-actually-needs", "heading": "List the systems the first lane actually needs", "paragraphs": ["Start with the first task lane, not the full job description, and list every system that lane touches. A typical lane might need the shared inbox, the calendar, the document drive, the task board, and one reporting export. Write the exact permission level beside each system, such as view, comment, edit, or administer. If you cannot name the level, the request is not ready for provisioning.", "Separate tools the assistant will use daily from tools that are only needed for a single handoff. Daily tools need a named account and a review date, while one-off tools can be handled through a supervised session. Include the client-facing name the assistant will use in email and chat. That detail prevents a new hire from improvising an identity that confuses customers.", "Walk the lane yourself before the start date and note every login prompt, shared folder, and approval screen. A tool that appears in the job description but not in the actual workflow should be removed from the request. A tool that appears only when an exception occurs should be documented as an exception path. The list should match the work, not the org chart."]}, {"id": "separate-named-accounts-from-shared-logins", "heading": "Separate named accounts from shared logins", "paragraphs": ["Every person should sign in with a named account, even when the team shares a mailbox or a calendar. Named accounts make it possible to see who changed a record, who exported a file, and who approved a request. Shared credentials erase that evidence and make removal impossible without disrupting everyone else. If a tool truly cannot support individual users, document the exception and the compensating review.", "Multi-factor authentication belongs on every account that supports it, including email, file storage, and the task board. Give the assistant a recovery method that does not depend on the manager's personal phone. Record the device and the backup code location in the access register. A login that only works when one supervisor is awake is not a reliable first-week setup."]}, {"id": "stage-permissions-by-task-risk", "heading": "Stage permissions by task risk", "paragraphs": ["Grant the smallest permission that lets the assistant complete the first reviewed task, then add rights after evidence. A new assistant can usually draft replies before sending them, prepare calendar changes before applying them, and stage files before moving them into client folders. Keep export, delete, billing, and user administration rights with a limited owner group. The staged approach gives the reviewer a chance to catch a misunderstanding before it reaches a client.", "Write the promotion rule in advance, for example two weeks of clean samples and one reviewer sign-off. Without a written rule, access expands through convenience and nobody remembers who approved it. Put the rule in the same register as the grant so the next reviewer can see the expected date. Review every temporary grant on its stated expiry rather than waiting for an incident.", "Match the permission to the consequence of a mistake, not to the seniority of the person. A wrong draft is easy to correct, while a wrong export or deletion can be permanent. If a task needs a high-risk permission, add a second reviewer or a shorter review interval. The extra step is cheaper than a client incident.", "Give the assistant a way to report a permission that is too broad without fearing blame for the request. A short weekly note asking what access felt unnecessary will surface rights that were granted by habit. Record the answer in the register and act on it during the review. The person doing the work often sees the excess before the manager does."]}, {"id": "record-the-approver-for-every-grant", "heading": "Record the approver for every grant", "paragraphs": ["The access register should show the system, account name, permission level, requester, approver, grant date, and review date. Add a field for the business reason so a later reviewer understands why the right exists. Link the register to the role brief instead of storing it in a chat message. A grant without an approver is an orphan, even if the tool shows the account as active.", "Ask the client to approve any access to client-owned systems in writing. Keep that approval with the contract or the onboarding record, not only in email. If the client delegates approval to the provider, name the individual who holds that authority. Clear approval ownership shortens the removal conversation later and gives the client a record it can audit."]}, {"id": "schedule-the-first-access-review", "heading": "Schedule the first access review", "paragraphs": ["Book a review at the end of week one and again at the end of the first month. The first review checks whether the assistant can actually do the work with the rights granted, and the second checks whether the rights still match the lane. Invite the assistant to report missing access and unnecessary access in the same conversation. A review that only asks whether the work was completed will miss both problems.", "Compare the register with the tool's own user list rather than trusting the register alone. Remove anything that cannot be tied to a current task, a current client, or a legal retention duty. Record the removal date and the person who performed it. If a tool has no exportable user list, take a dated screenshot and store it with the review.", "Keep the review notes in the same system as the grant so the next reviewer does not have to reconstruct the history. A screenshot folder on a laptop is not a shared record. If the tool supports comments, attach the review note to the account entry. A review that cannot be found later has limited value."]}, {"id": "plan-removal-before-day-one-ends", "heading": "Plan removal before day one ends", "paragraphs": ["Write the removal steps on the first day, while the account is still easy to trace. Name the owner for each system, the order of removal, and the evidence that proves the account is disabled. Include the mailbox delegation, calendar sharing, password manager entry, and any forwarding rule the assistant created. A removal plan written after a departure is usually incomplete.", "Test one removal in a safe account before the first live grant. The test should show that the account loses access, the manager retains the data, and the client receives a confirmation. Store the test result with the access register. That small rehearsal turns offboarding from a scramble into a checklist the team has already run."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "set-response-time-standards-your-va-can-actually-meet", "title": "Set response-time standards your VA can actually meet", "description": "Define the clock, coverage window, and escalation path behind a response-time promise so a virtual assistant can meet the standard during real volume instead of only on quiet days.", "published": "2026-11-06", "readingMinutes": 5, "heroImage": "/hero/november-6/set-response-time-standards-your-va-can-actually-meet-hero.webp", "thumbnail": "/thumbnails/november-6/set-response-time-standards-your-va-can-actually-meet.webp", "heroAlt": "Set response-time standards your VA can actually meet", "topic": "response-time standards", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/how-consistent-are-va-response-time-promises-across-providers", "label": "Read the response-time promise research review"}, "sources": [{"label": "FTC truth in advertising", "href": "https://www.ftc.gov/business-guidance/resources/truth-advertising"}, {"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "define-the-clock-that-starts-the-measurement", "heading": "Define the clock that starts the measurement", "paragraphs": ["A response-time standard needs a start event that everyone can see, such as the moment a message lands in the shared inbox. If the clock starts when someone notices the message, the measurement rewards attention rather than service. Write the start event, the working calendar, and the time zone into the standard. Then test the definition against last month's threads before publishing it.", "Decide whether weekends, holidays, and client closures pause the clock. A standard that ignores the calendar will look excellent in December and terrible in January. Record the coverage window in the same place as the promise so a reviewer can calculate the target. When the client operates in another time zone, state which zone governs the clock.", "Test the definition on one unusual week before you announce it. A holiday week, a product launch, or a billing cycle will show whether the clock behaves the way the client expects. Adjust the exclusions rather than explaining away the miss later. The published standard should survive the calendar, not ignore it."]}, {"id": "separate-first-response-from-resolution", "heading": "Separate first response from resolution", "paragraphs": ["First response proves that the request entered a queue, while resolution proves that the work is finished. Combine them into one number and the team will optimize the easy part. Publish two standards: an acknowledgement within the coverage window and a resolution target by request type. Put the owner and the next action in the acknowledgement so the client knows what happens next.", "Some requests should never receive a fast resolution, such as a refund, a legal question, or a change to a contract. For those, the standard should require a fast acknowledgement and a named reviewer. Tell the client which categories work this way before the first request arrives. That distinction prevents an assistant from guessing just to hit a number.", "Write one example of a good acknowledgement and one of a bad one. The good example names the owner, the next action, and the time of the next update. The bad example says only that the request was received. Assistants copy examples more reliably than they follow abstract rules, so the pair does more work than another paragraph of policy."]}, {"id": "group-work-by-channel-and-urgency", "heading": "Group work by channel and urgency", "paragraphs": ["A single inbox standard hides the difference between a chat message, an email, and a task-board ticket. Group requests by channel and by consequence, then set a target for each group. A password reset for a locked employee may need a faster response than a newsletter request. A client escalation may need an immediate acknowledgement even when the fix takes days.", "Keep the number of groups small enough to remember, usually three to five. Give each group a plain name that the client and the assistant use in the same way. Publish examples for the boundary cases, such as a request that arrives by email but concerns an urgent customer issue. Examples reduce the daily argument about which clock applies.", "Review the groups after the first month and merge any that produce the same behavior. A group that nobody can assign confidently is a source of delay, not a service tier. Rename the groups in the client's language rather than in internal shorthand. The client should be able to predict which target applies before sending the request."]}, {"id": "publish-coverage-windows-with-time-zones", "heading": "Publish coverage windows with time zones", "paragraphs": ["Write the coverage window in the client's time zone and the assistant's time zone, then show the overlap in plain language. State the handoff time when the primary assistant stops and the backup begins. Include the channel where urgent issues should go outside the window. A promise without a coverage window is really a hope.", "Check the window against actual staffing rather than the contract's advertised hours. If the backup is unavailable on Friday afternoon, do not publish a Friday promise that depends on the backup. Review the window when a client adds a region, a shift, or a new channel. The standard should change when coverage changes, not after the first missed request."]}, {"id": "handle-breaches-with-a-named-owner", "heading": "Handle breaches with a named owner", "paragraphs": ["Define a breach as a request that passed its target without a response or a documented next step. Route the breach to a named owner who can reassign work, adjust the client's expectation, or approve extra coverage. Record the cause in a short list such as volume, missing access, unclear request, or reviewer delay. A breach log without a cause becomes a scoreboard rather than a repair tool.", "Tell the client about a breach before the client discovers it, especially when the delay affects a commitment. Use a short note that states what happened, what is being done, and when the next update will arrive. Do not promise a root cause before the review is complete. Honest timing protects trust better than a quiet recovery.", "Review the breach log for breaches that were never visible to the client because the assistant fixed them quietly. A quiet fix is good service, but it can hide a capacity problem. Record the near-miss with the same cause code and review it alongside the visible breach. The pattern matters more than the individual save."]}, {"id": "review-the-standard-against-real-volume", "heading": "Review the standard against real volume", "paragraphs": ["Once a month, compare the published targets with the actual arrival pattern and the actual staffing. If most requests arrive in a two-hour window, a standard that assumes an even flow will fail every morning. Shift coverage, batch low-priority work, or change the target based on evidence. The standard is a service promise, not a performance slogan.", "Ask the assistants which requests consume the most time and which rules cause the most questions. Their answers usually reveal a missing template, an unclear owner, or a tool that forces extra steps. Fix the cause before tightening the target. A faster standard built on a broken workflow only teaches the team to cut corners."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "build-a-client-offboarding-handback-packet", "title": "Build a client offboarding handback packet", "description": "A step-by-step handback packet for ending a virtual assistant engagement: files, accounts, open commitments, access evidence, and the client confirmation that closes the loop.", "published": "2026-11-06", "readingMinutes": 5, "heroImage": "/hero/november-6/build-a-client-offboarding-handback-packet-hero.webp", "thumbnail": "/thumbnails/november-6/build-a-client-offboarding-handback-packet.webp", "heroAlt": "Build a client offboarding handback packet", "topic": "client offboarding handback", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/what-does-access-removal-lag-look-like-after-an-assignment-ends", "label": "Read the access removal research review"}, "sources": [{"label": "FTC protecting personal information guide", "href": "https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business"}, {"label": "NIST SP 800-53 Rev. 5, Security and Privacy Controls", "href": "https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"}, {"label": "HHS HIPAA Security Rule", "href": "https://www.hhs.gov/hipaa/for-professionals/security/index.html"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "start-the-packet-when-notice-arrives", "heading": "Start the packet when notice arrives", "paragraphs": ["Open the handback packet on the day notice arrives, even if the last working day is weeks away. List the notice date, the final service date, the client contact, and the internal owner for the transition. Put the packet in a shared location that both parties can reach without asking the departing assistant. Starting early gives the client time to name a receiver and challenge the inventory.", "Confirm which services end and which continue under a new scope. A client may end one lane while keeping another, and a blended exit is harder than a full stop. Write the boundary in the packet so nobody assumes the whole relationship is closing. Send the client a short summary of the plan within two business days.", "Assign a transition owner who is not the departing assistant. That person should be able to answer questions, approve file access, and sign off on the final packet. If the client has a different contact for the exit, record both names and their responsibilities. A transition with no internal owner tends to stall when the assistant leaves."]}, {"id": "inventory-files-accounts-and-open-commitments", "heading": "Inventory files, accounts, and open commitments", "paragraphs": ["Build three lists: files the client owns, accounts the provider controls, and commitments still open. For each file, record the location, format, owner, and last update. For each account, record the system, the account name, the permission level, and who can disable it. For each commitment, record the request, the due date, and the next action.", "Include the unglamorous assets that are easy to forget, such as calendar sharing, mailbox rules, templates, saved searches, and password manager entries. Check for documents stored in personal drives or local downloads. A handback that returns the main folder but leaves working copies scattered across devices is not complete. Add the browser bookmarks and saved form entries that contain client information, because they are easy to overlook and hard to reconstruct.", "Give each item a status that a reviewer can read at a glance: delivered, pending, blocked, or not applicable. Add the evidence link for anything marked delivered. A list without status invites a second round of questions after the final meeting. The status column also makes the client's remaining actions visible.", "Decide who owns the client relationship after the handback. A client may need a new contact for billing, a new contact for service questions, and a different contact for data requests. Put those names in the packet before the last week. A handback that leaves the client with no route for follow-up feels like an abandonment, even when the work was delivered."]}, {"id": "return-the-client-s-data-in-usable-formats", "heading": "Return the client's data in usable formats", "paragraphs": ["Ask the client which formats they can open and which systems they will keep. Export spreadsheets as spreadsheets, not as pdf prints, and keep the original files where the client wants them. Include a manifest that maps each delivered file to its source and version. Test one export before producing the full set.", "Remove provider-internal notes, drafts, and unrelated client records before delivery. If a file contains both client data and internal commentary, separate the two rather than sending the whole document. Record any file that cannot be delivered and explain why. A clean handback protects the client and reduces the provider's own risk.", "Confirm the delivery channel before the final week. A large export may need a secure transfer link, an encrypted drive, or a direct upload to the client's system. Test the recipient's access while the team is still available to fix it. A packet that arrives after the last working day is much harder to repair."]}, {"id": "close-access-with-dated-evidence", "heading": "Close access with dated evidence", "paragraphs": ["Disable the assistant's accounts in a planned order, starting with the broadest access and ending with the tools needed to finish the handback. Record the time, the system, the person who performed the change, and the confirmation the tool returned. Ask the client to confirm that their own user list no longer shows the provider account. Keep the evidence with the handback packet.", "Check for shared credentials, API tokens, forwarding rules, and device enrollments that a normal user list may not show. Revoke sessions as well as passwords, because an active session can outlive a password change. If a system cannot be audited, document the limitation and the compensating control. An access close that relies on a verbal assurance is not evidence.", "Record the order in which access will be removed and the work that depends on each system. Removing the document drive before the final export will stop the handback, while leaving the inbox open after the last day extends exposure. Sequence the removal around the work, not around the tool list. Share the sequence with the client so nobody is surprised by a lost login."]}, {"id": "hand-over-the-open-work-list", "heading": "Hand over the open work list", "paragraphs": ["Give the receiver a dated list of every open request, including the requester, the current state, the next action, and the deadline. Mark the items that need a decision rather than more work. Add the source of each instruction so the receiver can verify it. A list that only names the task will force the receiver to rebuild the context.", "Walk through the list in a live session and let the receiver ask questions. Record the answers beside the relevant item instead of leaving them in a meeting note. Confirm which items the provider will finish and which move to the client. Close the session with a named owner for every remaining item."]}, {"id": "confirm-receipt-and-remaining-obligations", "heading": "Confirm receipt and remaining obligations", "paragraphs": ["Send a final handback summary that lists what was delivered, what was removed, and what remains open. Ask the client to confirm receipt in writing and to name any missing item within an agreed window. Keep the confirmation with the contract record. The confirmation is the difference between a closed transition and a dispute waiting to happen.", "Review the packet after thirty days for any late request, retained file, or access issue. Update the record if the client reports a gap, and keep the correction with the original evidence. Use the review to improve the template for the next client. A handback process earns trust only when it survives the quiet month after the work stops."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "run-a-weekly-capacity-review-without-guesswork", "title": "Run a weekly capacity review without guesswork", "description": "A repeatable weekly review that counts demand, measures queue age, finds the real constraint, and records what to stop, shift, or add for a virtual assistant team.", "published": "2026-11-06", "readingMinutes": 4, "heroImage": "/hero/november-6/run-a-weekly-capacity-review-without-guesswork-hero.webp", "thumbnail": "/thumbnails/november-6/run-a-weekly-capacity-review-without-guesswork.webp", "heroAlt": "Run a weekly capacity review without guesswork", "topic": "weekly capacity review", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/how-much-va-time-is-lost-to-unclear-task-instructions", "label": "Read the unclear-instruction research review"}, "sources": [{"label": "NIST Baldrige Excellence Framework", "href": "https://www.nist.gov/baldrige"}, {"label": "BLS American Time Use Survey", "href": "https://www.bls.gov/tus/"}, {"label": "U.S. Small Business Administration hire and manage employees", "href": "https://www.sba.gov/business-guide/manage-your-business/hire-manage-employees"}], "sections": [{"id": "count-demand-before-discussing-hours", "heading": "Count demand before discussing hours", "paragraphs": ["Start the weekly review with the work that arrived, not the hours the team logged. Count requests by channel, client, and type, then separate new work from follow-ups. A week with high logged hours may still have low output if most time went to waiting or rework. Put the demand count beside the capacity number before anyone offers an opinion.", "Use a consistent counting rule so week-over-week comparisons mean something. Count one request per distinct outcome, not one per message in a thread. Record the source of the count, such as the inbox export or the task board. If the source changes, note the break rather than pretending the trend is continuous.", "Show the arrival pattern by day and hour, not only the weekly total. A team can be fully staffed on paper and still fail every Monday morning because the work arrives in a two-hour window. The pattern tells you where to place the buffer. A total without a shape hides the operational problem.", "Keep the counting rule beside the report so a new reviewer can reproduce the number. If a request is split across two channels, count it once at the point of origin and note the second channel. A rule that changes with the reviewer turns the trend into a story. The count should be boring enough to trust."]}, {"id": "separate-recurring-work-from-one-off-requests", "heading": "Separate recurring work from one-off requests", "paragraphs": ["Recurring work has a predictable cadence and a known owner, while one-off work arrives without a schedule. Split the two because they consume capacity differently and need different planning. Recurring work can be leveled across the week, while one-off work needs a buffer or a queue. A review that blends them hides the real reason a Thursday collapses.", "Tag the one-off requests that recur often enough to become a standard task. A client who asks for the same report every month is creating recurring work without a recurring slot. Move that work into the schedule or price it as a project. The tag turns a surprise into a planning decision."]}, {"id": "measure-queue-age-instead-of-activity", "heading": "Measure queue age instead of activity", "paragraphs": ["Activity counts such as messages sent or tasks touched can rise while the queue gets worse. Measure the age of the oldest open item and the number of items past their target. Add the time a request waits for a decision, because waiting is often the largest hidden cost. These measures show whether capacity is reaching the work that matters.", "Review the age distribution rather than only the average, since one old item can disappear inside a healthy mean. List the five oldest items and their blockers at every weekly review. Assign an owner and a next action to each. A queue that is reviewed by age is harder to neglect than a queue reviewed by volume.", "Separate queue age from task age. A request can sit in a triage queue for two days and then be completed in an hour, while another task can age slowly inside a single owner's list. Both waits matter, but they need different fixes. Report them separately so the review does not blame the wrong stage."]}, {"id": "identify-the-real-constraint-in-the-lane", "heading": "Identify the real constraint in the lane", "paragraphs": ["The constraint is the step that limits the whole lane, not the person who looks busiest. It might be a single approver, a missing report, a slow client response, or a tool that requires manual entry. Trace a sample of requests from arrival to completion and mark where each one waited longest. The pattern usually points to one or two constraints.", "Test the constraint before adding hours. If every request waits for the same reviewer, a new assistant will simply create more work for that reviewer. Fix the approval path, delegate a narrow decision, or batch the reviews. Add capacity only when the constraint is genuinely assistant time.", "Name the constraint in one sentence and test it with a small change before committing to a hire or a schedule change. If the change does not move the queue, the constraint was misidentified. Record the test and the result in the next review. A constraint that survives a test is a much stronger basis for spending money."]}, {"id": "decide-what-to-stop-shift-or-add", "heading": "Decide what to stop, shift, or add", "paragraphs": ["Every capacity review should end with a short decision list: what to stop, what to shift, and what to add. Stopping might mean retiring a low-value report or declining a request that is outside scope. Shifting might mean moving a task to a different day or a different assistant. Adding should name the hours, the owner, and the start date.", "Put a cost or consequence beside each option so the decision is not purely emotional. A report that takes four hours but nobody reads is a candidate for retirement. A task that blocks a client deliverable may justify extra coverage. Record the decision and the expected effect so the next review can check it."]}, {"id": "record-the-capacity-decision-for-next-week", "heading": "Record the capacity decision for next week", "paragraphs": ["Close the review with one page that shows demand, capacity, the constraint, and the decisions. Send it to the people who can change the schedule or the scope. Keep the page short enough to read in five minutes. A decision that lives only in a meeting will be relitigated by Thursday.", "At the next review, check whether the decision changed the measure it was meant to change. If it did not, record why before choosing another action. Capacity planning improves through these small, dated tests. The goal is not a perfect forecast but a team that notices drift early."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "turn-a-voice-note-handoff-into-a-searchable-task-record", "title": "Turn a voice-note handoff into a searchable task record", "description": "Convert a quick voice memo into a structured, searchable task record with clear outcomes, sources, tags, receiver confirmation, and a safe audio retention rule.", "published": "2026-11-06", "readingMinutes": 5, "heroImage": "/hero/november-6/turn-a-voice-note-handoff-into-a-searchable-task-record-hero.webp", "thumbnail": "/thumbnails/november-6/turn-a-voice-note-handoff-into-a-searchable-task-record.webp", "heroAlt": "Turn a voice-note handoff into a searchable task record", "topic": "voice-note handoff", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/where-do-shared-inbox-duplicate-replies-originate", "label": "Read the shared-inbox research review"}, "sources": [{"label": "NIST SP 800-92, Guide to Computer Security Log Management", "href": "https://csrc.nist.gov/pubs/sp/800/92/final"}, {"label": "NIST Privacy Framework", "href": "https://www.nist.gov/privacy-framework"}, {"label": "FTC protecting personal information guide", "href": "https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business"}], "sections": [{"id": "record-the-note-with-the-case-open", "heading": "Record the note with the case open", "paragraphs": ["Start the voice note only after the case record is open, so the audio has a place to land. Say the client, the request, the due date, and your name in the first fifteen seconds. A note that begins with background forces the receiver to listen twice. Keep the recording short enough to finish in one sitting.", "Use the same recording tool each time and store the file with the case, not in a personal chat. Name the file with the case key and the date. If the tool creates a transcript automatically, treat the transcript as a draft rather than the record. The case remains the source of truth even when the audio is lost.", "Check the recording before you send it. Listen for background noise, a missing name, or a sentence that trails off before the deadline. A ten-second replay catches most of the problems that force the receiver to call back. Delete and re-record rather than sending an apology and a correction."]}, {"id": "transcribe-the-instruction-into-fields", "heading": "Transcribe the instruction into fields", "paragraphs": ["Convert the note into the fields the receiver will actually use: requester, outcome, source, deadline, owner, and next action. Write the outcome as a result, not as an activity, so the receiver knows what finished looks like. Put the source beside any fact that came from a client message. Leave a field blank only when the note genuinely lacks the information.", "Separate the request from the suggested method. A client may ask for a report and suggest a format, but the required outcome may be the decision the report supports. Record both, with the request first. That separation lets the receiver change the method without changing the commitment.", "Write the record in plain language rather than in shorthand that only the recorder understands. Spell out a system name the first time and avoid internal abbreviations that a new assistant has not learned. The receiver should not need the audio to understand the field values. If a sentence needs the recording to make sense, rewrite it.", "Put the deadline in the record as a date and a time zone, not as a relative phrase. A note that says end of day is ambiguous when the receiver works in another region. Use the client's deadline and the assistant's working hours in separate fields if they differ. The receiver should not have to infer which clock the sender meant."]}, {"id": "tag-the-record-for-later-search", "heading": "Tag the record for later search", "paragraphs": ["Add tags that match the way the team searches, such as client, system, request type, and status. Avoid tags that only make sense to the person who recorded the note. Use the same vocabulary as the task board and the inbox labels. A tag that nobody else uses is a private note, not a handoff.", "Check that the record can be found by searching for the client name and the outcome. If the search returns nothing, the tags or the title need work. Test the search with a colleague who did not hear the audio. Their success is the real measure of whether the handoff is searchable.", "Keep the tag list short enough to scan and long enough to separate the common request types. Review it every quarter and remove tags that no longer appear in the queue. A stale tag creates false confidence because the search returns old work. The vocabulary should follow the work, not the other way around."]}, {"id": "confirm-the-receiver-understood-the-task", "heading": "Confirm the receiver understood the task", "paragraphs": ["Ask the receiver to restate the outcome, the deadline, and the first action in their own words. Do this in the case record so the confirmation is visible to the next reviewer. Correct any misunderstanding before the receiver starts work. A quick restatement is cheaper than a rebuilt deliverable.", "If the receiver cannot restate the task, the note is incomplete rather than the receiver being slow. Add the missing field and ask again. Record the exchange beside the case. The handoff is complete only when both people agree on what finished means."]}, {"id": "retire-the-audio-after-the-record-is-verified", "heading": "Retire the audio after the record is verified", "paragraphs": ["Keep the audio only as long as the record needs it for verification or dispute. Once the text is confirmed, move the audio to the retention location or delete it under the client's policy. Do not leave voice notes in a chat history where they cannot be found or removed. The record should stand without the audio.", "Check the retention rule before deleting anything that supports a client commitment or a billing question. If the audio contains sensitive information, store it with the same controls as the written record. Record the deletion date and the person who approved it. A clean audio lifecycle is part of a trustworthy handoff.", "Store the deletion decision with the case so a later reviewer can see why the audio is gone. If the client requires the audio for a fixed period, record the end date and the owner who will delete it. A retention rule that lives only in a policy document is easy to miss. The case should carry the specific instruction that applied."]}, {"id": "fix-the-template-after-three-notes", "heading": "Fix the template after three notes", "paragraphs": ["Review the first three voice-note handoffs and look for fields that were always missing or always rewritten. Those gaps usually mean the note template is asking the wrong question. Change the template, then test it with the next handoff. Do not ask the team to try harder at a format that does not fit the work.", "Share one strong example and one corrected example with the team. Keep both beside the template so a new assistant can see the standard. Update the examples when the template changes. The goal is a handoff that any scheduled assistant can pick up without replaying a recording."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "audit-a-shared-inbox-for-duplicate-work", "title": "Audit a shared inbox for duplicate work", "description": "Trace duplicate replies to their routing cause with a dated export, owner comparison, and a before-and-after check that fixes the rule instead of blaming the assistant.", "published": "2026-11-06", "readingMinutes": 4, "heroImage": "/hero/november-6/audit-a-shared-inbox-for-duplicate-work-hero.webp", "thumbnail": "/thumbnails/november-6/audit-a-shared-inbox-for-duplicate-work.webp", "heroAlt": "Audit a shared inbox for duplicate work", "topic": "shared inbox audit", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/where-do-shared-inbox-duplicate-replies-originate", "label": "Read the duplicate reply research review"}, "sources": [{"label": "NIST SP 800-92, Guide to Computer Security Log Management", "href": "https://csrc.nist.gov/pubs/sp/800/92/final"}, {"label": "FTC protecting personal information guide", "href": "https://www.ftc.gov/business-guidance/resources/protecting-personal-information-guide-business"}, {"label": "NIST Privacy Framework", "href": "https://www.nist.gov/privacy-framework"}], "sections": [{"id": "export-the-thread-list-with-timestamps", "heading": "Export the thread list with timestamps", "paragraphs": ["Begin with a dated export of the shared inbox, including sender, recipient, subject, labels, assignee, and the first and last message times. Export the thread list rather than a folder of individual messages, because duplicates usually appear across a conversation. Store the export read-only so the audit cannot change the mailbox. Record the export window and the time zone.", "If the inbox tool cannot export the needed fields, take a consistent screenshot set and record the limitation. Do not rely on memory or a few open tabs. The audit needs the same evidence a reviewer would use to reconstruct the day. A partial export can still be useful if the gap is stated.", "Include the sent folder and any shared alias that can send on behalf of the team. A duplicate may never appear in the inbox if one owner replied from a different address. Note the alias in the export so the reviewer can match the sender to a person. The address list is part of the routing evidence."]}, {"id": "group-messages-by-customer-and-topic", "heading": "Group messages by customer and topic", "paragraphs": ["Group threads by customer and by the underlying request, not by subject line. Subject lines drift when people reply or forward, so the same request can appear under three different labels. Use the customer domain, the order number, or the case key when one exists. For each group, count the distinct outcomes requested.", "Mark the groups that received more than one substantive reply from different owners. A short acknowledgement from a second person is not a duplicate if the first owner was waiting. Look for replies that answer the same question differently. Those are the threads that create confusion for the customer.", "Record the first and last reply in each group so the review can see whether the second answer corrected the first or contradicted it. A correction is less damaging than a contradiction, but both waste the customer's attention. Note whether the customer replied after the duplicate and which answer they followed. That detail shows the real cost."]}, {"id": "find-replies-sent-from-more-than-one-owner", "heading": "Find replies sent from more than one owner", "paragraphs": ["Compare the sender list with the assignee field for each thread. When two people reply without a handoff note, the customer sees two voices and may act on the wrong one. Record the time gap between the replies and whether either owner saw the other's message. A gap under five minutes often means both were working the same arrival.", "Check the sent folder rather than only the inbox, because a duplicate may be invisible from the receiving side. Look for internal notes that say someone else is handling the request. If the note exists but the reply still went out, the problem is the handoff rule rather than the people. Read the timestamps on those notes to see whether the second owner replied before or after the claim.", "Check whether the second reply was sent with a different template or signature. A different template often means the second owner did not see the first reply, while the same template may mean the team is copying an old response. The detail helps distinguish a visibility problem from a training problem. Record it beside the thread."]}, {"id": "check-internal-notes-for-conflicting-instructions", "heading": "Check internal notes for conflicting instructions", "paragraphs": ["Read the internal notes on the duplicate threads and mark where the instructions conflict. One note may say the client wants a call, while another says the client prefers email. Record the source and date of each instruction. Conflicting notes are a sign that the client's preferences are not stored in one place.", "Look for notes that were copied from an older thread without a date. An instruction without a date cannot be ranked against a newer one. Ask the owner to confirm the current preference and update the source record. The audit should fix the record, not just flag the thread."]}, {"id": "fix-routing-rules-before-adding-staff", "heading": "Fix routing rules before adding staff", "paragraphs": ["If duplicates cluster around one label or one client, fix the routing rule before hiring another assistant. A rule that sends every message to a general queue guarantees that two people will eventually open the same request. Assign a primary owner by client, topic, or time window, and write the handoff trigger. Then test the rule with a sample of live messages.", "Keep one shared view for unassigned work and require an owner before a reply is sent. Make the assignment visible in the thread so the second person can see it. If the tool cannot show ownership, use a short internal note with the owner and the time. The fix should reduce duplicate replies without slowing the first response.", "Give the new routing rule a short trial before you change the whole inbox. Apply it to one client or one label and compare the duplicate rate with the rest of the queue. A small trial limits the damage if the rule sends work to the wrong owner. Expand it only after the trial shows a clear improvement."]}, {"id": "recheck-a-sample-after-the-routing-change", "heading": "Recheck a sample after the routing change", "paragraphs": ["Wait one full coverage cycle, then export the same fields and compare the duplicate rate. Check whether the same customers appear again and whether the replies now carry one owner. Read a sample of threads rather than trusting the count alone. A lower count can hide a new pattern of silent handoffs.", "Record the before-and-after evidence, the rule change, and the remaining exceptions. Share the result with the assistants who work the inbox, because they will notice the edge cases the report misses. Set a date for the next check. Duplicate work is a process symptom, and the audit is only useful if it changes the process."]}]}, {"publicationStatus": "reviewed", "kind": "blog", "slug": "design-an-escalation-matrix-for-routine-va-work", "title": "Design an escalation matrix for routine VA work", "description": "Give every routine virtual assistant decision a trigger, a named owner, a backup, and an evidence template so exceptions move instead of sitting in the queue.", "published": "2026-11-06", "readingMinutes": 4, "heroImage": "/hero/november-6/design-an-escalation-matrix-for-routine-va-work-hero.webp", "thumbnail": "/thumbnails/november-6/design-an-escalation-matrix-for-routine-va-work.webp", "heroAlt": "Design an escalation matrix for routine VA work", "topic": "escalation matrix design", "relatedService": {"href": "/services", "label": "Explore staffing services"}, "relatedResource": {"href": "/research/what-share-of-va-escalations-lack-a-named-decision-owner", "label": "Read the escalation ownership research review"}, "sources": [{"label": "NIST SP 800-61 Rev. 2, Computer Security Incident Handling Guide", "href": "https://csrc.nist.gov/pubs/sp/800/61/r2/final"}, {"label": "NIST Cybersecurity Framework 2.0", "href": "https://www.nist.gov/cyberframework"}, {"label": "CISA incident and vulnerability response playbooks", "href": "https://www.cisa.gov/resources-tools/resources/federal-government-cybersecurity-incident-and-vulnerability-response-playbooks"}], "sections": [{"id": "list-the-decisions-an-assistant-cannot-make", "heading": "List the decisions an assistant cannot make", "paragraphs": ["Start with the decisions that require the client, a manager, or a specialist, such as refunds, contract changes, legal threats, and personnel matters. Write each decision as a plain category rather than a job title. Include the routine-looking requests that still carry commitments, such as rescheduling a delivery or promising a discount. The list should be short enough to use during a busy afternoon.", "Ask the assistants which requests they were unsure about in the last month. Their answers will surface decisions that are missing from the written scope. Add the real examples beside the category so the boundary is concrete. A matrix built only from the contract will miss the daily reality.", "Separate a decision from a task that merely needs a second pair of eyes. A proofreading request can be reviewed by a peer, while a refund needs an accountable owner. Mixing the two makes the matrix feel heavier than it needs to be. Keep the approval categories narrow and the review categories light."]}, {"id": "name-one-owner-per-decision-type", "heading": "Name one owner per decision type", "paragraphs": ["Every category needs one accountable owner and one backup, with a named channel for the escalation. An owner is a person who can decide, not a team inbox that everyone monitors. Record the owner's coverage window and the expected response time. If no owner exists, the category is not ready for the matrix.", "Separate the decision owner from the person who prepares the evidence. The assistant can gather the thread, the policy, and the customer history, but the owner makes the call. Write that split into the matrix so the assistant does not feel responsible for an outcome outside their authority. The split also makes the escalation faster."]}, {"id": "set-trigger-conditions-and-time-limits", "heading": "Set trigger conditions and time limits", "paragraphs": ["A trigger is the observable condition that starts an escalation, such as a request that exceeds the approved amount or a customer who mentions a lawyer. Write the trigger in language the assistant can recognize without interpreting intent. Add a time limit for the escalation, because a message that waits all day is not really escalated. Test the trigger against real examples from the queue.", "Include a default path for requests that match no category. The default should route to a named general owner rather than back to the assistant. Set a shorter limit for the default path so an unknown request does not sit unresolved. Review the default path monthly for requests that should become a new category.", "Use a clock the assistant can see, such as the case timestamp or the coverage window. A limit expressed only as soon creates different expectations on different days. Write the limit in the same place as the trigger. The assistant should not have to decide whether a request is urgent enough to interrupt someone.", "Write the trigger in the client's language as well as the internal shorthand. A client may describe a request as urgent without saying it involves a legal threat, while the assistant needs the observable fact. Put both versions in the matrix so the assistant can match the message to the rule. The translation step is where many escalations are missed."]}, {"id": "define-the-information-an-escalation-must-carry", "heading": "Define the information an escalation must carry", "paragraphs": ["An escalation should carry the requester, the request, the relevant history, the rule that triggered it, and the decision needed. Add the deadline and the consequence of missing it. Link the source message rather than pasting a summary that may lose detail. A complete escalation lets the owner decide without reopening the whole thread.", "Write a short template and require the same fields every time. The template should take less than two minutes to complete. If an escalation arrives without the fields, return it with a specific request rather than guessing. Consistency makes the escalation log useful for review."]}, {"id": "test-the-matrix-with-a-tabletop-case", "heading": "Test the matrix with a tabletop case", "paragraphs": ["Pick a realistic request and walk it through the matrix with the assistant and the owner. Time how long it takes to identify the trigger, find the owner, and prepare the evidence. Note every place where the matrix is ambiguous or the owner is unavailable. Fix those gaps before the next live case.", "Run a second test outside normal hours to check the backup path. A matrix that only works when the primary owner is at the desk is not a coverage plan. Record the result and the changes. The test is cheap, and it exposes the difference between a written rule and a usable one.", "Invite the client to the tabletop test when the decision affects their money, data, or reputation. The client may reveal an approval path that the provider did not know existed. Record the client's answer as part of the matrix, not as a side note. A tested path with the client present is stronger than an internal assumption."]}, {"id": "review-escalations-for-missing-owners", "heading": "Review escalations for missing owners", "paragraphs": ["Each month, list the escalations that had no named owner, no response, or a reassignment. Group them by cause and check whether the matrix needs a new category, a new backup, or a clearer trigger. Read two or three actual messages to understand the delay. A count without a story rarely leads to a fix.", "Share the findings with the client and the assistants, then update the matrix in the same week. Remove categories that no longer occur and add the ones that emerged. Keep the version date visible. An escalation matrix is a living document, and its value depends on the review loop behind it."]}]}];
